ALTER TABLE public.delivery_jobs ADD COLUMN pickup_lat double precision, ADD COLUMN pickup_lng double precision, ADD COLUMN assignment_state text NOT NULL DEFAULT 'available', ADD COLUMN accepted_at timestamptz, ADD COLUMN pickup_started_at timestamptz, ADD COLUMN pickup_arrived_at timestamptz, ADD COLUMN collected_at timestamptz, ADD COLUMN destination_arrived_at timestamptz, ADD COLUMN cancelled_at timestamptz, ADD COLUMN failed_at timestamptz, ADD COLUMN returned_at timestamptz, ADD COLUMN exception_reason text;
ALTER TABLE public.delivery_job_events ADD COLUMN action text, ADD COLUMN previous_status text, ADD COLUMN new_status text, ADD COLUMN actor_role text;
UPDATE public.delivery_jobs SET assignment_state='assigned' WHERE rider_id IS NOT NULL;
ALTER TABLE public.delivery_jobs DROP CONSTRAINT delivery_jobs_status_check;
CREATE UNIQUE INDEX delivery_jobs_active_sale_unique ON public.delivery_jobs(sale_id) WHERE sale_id IS NOT NULL AND status NOT IN ('delivered','cancelled','returned');
CREATE INDEX delivery_job_events_job_created_idx ON public.delivery_job_events(job_id,created_at);
GRANT SELECT ON public.delivery_jobs,public.delivery_job_events TO authenticated;
GRANT ALL ON public.delivery_jobs,public.delivery_job_events TO service_role;
REVOKE ALL ON public.delivery_jobs,public.delivery_job_events FROM anon;
REVOKE INSERT,UPDATE,DELETE ON public.delivery_jobs,public.delivery_job_events FROM authenticated;

CREATE FUNCTION public.delivery_workflow_status(_status text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _status WHEN 'pending' THEN 'in_process' WHEN 'accepted' THEN 'in_process' WHEN 'picked_up' THEN 'in_transit' ELSE _status END $$;
CREATE FUNCTION public.validate_delivery_coordinates(_lat double precision,_lng double precision) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (_lat IS NULL) <> (_lng IS NULL) OR (_lat IS NOT NULL AND NOT (_lat BETWEEN -90 AND 90 AND _lng BETWEEN -180 AND 180)) THEN RAISE EXCEPTION 'Provide both valid latitude (-90..90) and longitude (-180..180)'; END IF; END $$;
CREATE FUNCTION public.is_active_delivery_rider(_pharmacy uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role IN ('super_admin','pharmacy_owner','supplier','manager')) AND NOT EXISTS(SELECT 1 FROM public.pharmacies WHERE owner_id=_user) AND EXISTS(SELECT 1 FROM public.pharmacy_memberships WHERE pharmacy_id=_pharmacy AND user_id=_user AND role='delivery_rider' AND is_active=true AND employment_status='active') AND NOT EXISTS(SELECT 1 FROM public.pharmacy_memberships WHERE pharmacy_id=_pharmacy AND user_id=_user AND role='manager' AND is_active=true) $$;
CREATE FUNCTION public.delivery_event_context() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=NEW.job_id; NEW.action:=coalesce(NEW.action,CASE WHEN NEW.status='update' THEN 'note' ELSE NEW.status END); NEW.new_status:=coalesce(NEW.new_status,j.status); NEW.actor_role:=coalesce(NEW.actor_role,CASE WHEN public.is_active_delivery_rider(j.pharmacy_id,NEW.actor_id) THEN 'delivery_rider' WHEN public.has_role(NEW.actor_id,'super_admin') THEN 'super_admin' WHEN EXISTS(SELECT 1 FROM public.pharmacies WHERE id=j.pharmacy_id AND owner_id=NEW.actor_id) THEN 'owner' ELSE (SELECT role::text FROM public.pharmacy_memberships WHERE pharmacy_id=j.pharmacy_id AND user_id=NEW.actor_id AND is_active=true LIMIT 1) END,'system'); PERFORM public.validate_delivery_coordinates(NEW.lat,NEW.lng); RETURN NEW; END $$;
CREATE TRIGGER delivery_event_context BEFORE INSERT ON public.delivery_job_events FOR EACH ROW EXECUTE FUNCTION public.delivery_event_context();
CREATE FUNCTION public.delivery_event_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Delivery history is append-only'; END $$;
CREATE TRIGGER delivery_event_append_only BEFORE UPDATE OR DELETE ON public.delivery_job_events FOR EACH ROW EXECUTE FUNCTION public.delivery_event_append_only();
CREATE FUNCTION public.validate_delivery_job_workflow() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status NOT IN ('pending','accepted','picked_up','in_process','pickup','in_transit','arrived','delivered','cancelled','failed','returning','returned') THEN RAISE EXCEPTION 'Unknown delivery status'; END IF; IF NEW.assignment_state NOT IN ('available','assigned') OR (NEW.assignment_state='available' AND NEW.rider_id IS NOT NULL) OR (NEW.assignment_state='assigned' AND NEW.rider_id IS NULL) THEN RAISE EXCEPTION 'Invalid rider assignment'; END IF; PERFORM public.validate_delivery_coordinates(NEW.pickup_lat,NEW.pickup_lng); PERFORM public.validate_delivery_coordinates(NEW.dropoff_lat,NEW.dropoff_lng); PERFORM public.validate_delivery_coordinates(NEW.rider_lat,NEW.rider_lng); RETURN NEW; END $$;
CREATE TRIGGER validate_delivery_job_workflow BEFORE INSERT OR UPDATE ON public.delivery_jobs FOR EACH ROW EXECUTE FUNCTION public.validate_delivery_job_workflow();

CREATE FUNCTION public.create_sale_delivery(_sale uuid,_dropoff text,_recipient text,_phone text,_note text,_pickup_lat double precision,_pickup_lng double precision,_dropoff_lat double precision,_dropoff_lng double precision,_pickup_address text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sales; v uuid; pickup text; trk text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO s FROM public.sales WHERE id=_sale FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Sale not found'; END IF; IF NOT public.can_write_pharmacy(s.pharmacy_id,ARRAY['manager','pharmacist','cashier','inventory_manager']::public.user_role[]) OR NOT public.can_access_branch(s.pharmacy_id,s.branch_id) THEN RAISE EXCEPTION 'You cannot dispatch this sale'; END IF; SELECT id INTO v FROM public.delivery_jobs WHERE sale_id=_sale AND status NOT IN ('delivered','cancelled','returned'); IF FOUND THEN RETURN v; END IF; SELECT id INTO v FROM public.delivery_jobs WHERE sale_id=_sale AND status='delivered' ORDER BY created_at DESC LIMIT 1; IF FOUND THEN RETURN v; END IF; IF NOT public.pharmacy_has_plan_feature(s.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Delivery management requires an eligible current plan'; END IF; IF coalesce(trim(_dropoff),'')='' THEN RAISE EXCEPTION 'Delivery address is required'; END IF; PERFORM public.validate_delivery_coordinates(_pickup_lat,_pickup_lng); PERFORM public.validate_delivery_coordinates(_dropoff_lat,_dropoff_lng); SELECT coalesce(nullif(trim(_pickup_address),''),nullif(trim(b.address),''),nullif(concat_ws(', ',p.address,p.city),'')) INTO pickup FROM public.pharmacies p LEFT JOIN public.branches b ON b.id=s.branch_id WHERE p.id=s.pharmacy_id; LOOP trk:=public.next_tracking_number(s.pharmacy_id); BEGIN INSERT INTO public.delivery_jobs(tracking_number,pharmacy_id,sale_id,status,pickup_address,pickup_lat,pickup_lng,dropoff_address,dropoff_lat,dropoff_lng,recipient_name,recipient_phone,note,created_by) VALUES(trk,s.pharmacy_id,_sale,'in_process',pickup,_pickup_lat,_pickup_lng,trim(_dropoff),_dropoff_lat,_dropoff_lng,nullif(trim(_recipient),''),nullif(trim(_phone),''),nullif(trim(_note),''),auth.uid()) RETURNING id INTO v; EXIT; EXCEPTION WHEN unique_violation THEN SELECT id INTO v FROM public.delivery_jobs WHERE sale_id=_sale AND status NOT IN ('delivered','cancelled','returned'); IF FOUND THEN RETURN v; END IF; END; END LOOP; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,new_status,note) VALUES(v,'in_process',auth.uid(),'created','in_process','Sent from till'); RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.create_sale_delivery(_sale uuid,_dropoff text,_recipient text,_phone text,_note text) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.create_sale_delivery(_sale,_dropoff,_recipient,_phone,_note,NULL::double precision,NULL::double precision,NULL::double precision,NULL::double precision,NULL::text) $$;

CREATE FUNCTION public.accept_delivery_offer(_job uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF NOT public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) THEN RAISE EXCEPTION 'Only an active delivery rider of this business may accept'; END IF; IF NOT public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Delivery management requires an eligible current plan'; END IF; IF j.assignment_state<>'available' OR j.rider_id IS NOT NULL THEN RAISE EXCEPTION 'Delivery offer already accepted'; END IF; IF public.delivery_workflow_status(j.status)<>'in_process' THEN RAISE EXCEPTION 'Delivery is not available for acceptance'; END IF; UPDATE public.delivery_jobs SET rider_id=auth.uid(),assignment_state='assigned',accepted_at=now(),updated_at=now() WHERE id=_job; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status) VALUES(_job,j.status,auth.uid(),'offer_accepted',j.status,j.status); END $$;
CREATE OR REPLACE FUNCTION public.advance_delivery_job(_job uuid,_status text,_lat double precision,_lng double precision,_note text,_signature text,_signed_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; cur text; nxt text; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF j.rider_id IS DISTINCT FROM auth.uid() OR j.assignment_state<>'assigned' OR NOT public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) THEN RAISE EXCEPTION 'Only the assigned active rider may progress this delivery'; END IF; IF NOT public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Delivery management requires an eligible current plan'; END IF; PERFORM public.validate_delivery_coordinates(_lat,_lng); cur:=public.delivery_workflow_status(j.status); nxt:=CASE cur WHEN 'in_process' THEN 'pickup' WHEN 'pickup' THEN 'in_transit' WHEN 'in_transit' THEN 'arrived' WHEN 'arrived' THEN 'delivered' END; IF nxt IS NULL OR _status IS DISTINCT FROM nxt THEN RAISE EXCEPTION 'Delivery is %; exact next stage is %',j.status,coalesce(nxt,'none'); END IF; IF _status='in_transit' AND j.pickup_arrived_at IS NULL THEN RAISE EXCEPTION 'Record arrival at pickup before confirming collection'; END IF; IF _status='delivered' AND (coalesce(trim(_signed_name),'')='' OR length(_signed_name)>200 OR coalesce(_signature,'') !~ '^data:image/png;base64,[A-Za-z0-9+/]+={0,2}$' OR length(_signature)>400000 OR substring(coalesce(_signature,'') from 23 for 11)<>'iVBORw0KGgo') THEN RAISE EXCEPTION 'The receiver must give a name and valid PNG signature'; END IF; UPDATE public.delivery_jobs SET status=_status,updated_at=now(),pickup_started_at=CASE WHEN _status='pickup' THEN now() ELSE pickup_started_at END,collected_at=CASE WHEN _status='in_transit' THEN now() ELSE collected_at END,destination_arrived_at=CASE WHEN _status='arrived' THEN now() ELSE destination_arrived_at END,delivered_at=CASE WHEN _status='delivered' THEN now() ELSE delivered_at END,signature=CASE WHEN _status='delivered' THEN _signature ELSE signature END,signed_name=CASE WHEN _status='delivered' THEN trim(_signed_name) ELSE signed_name END,rider_lat=coalesce(_lat,rider_lat),rider_lng=coalesce(_lng,rider_lng),rider_seen_at=CASE WHEN _lat IS NOT NULL THEN now() ELSE rider_seen_at END WHERE id=_job; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,lat,lng,note) VALUES(_job,_status,auth.uid(),CASE _status WHEN 'pickup' THEN 'pickup_started' WHEN 'in_transit' THEN 'collected' WHEN 'arrived' THEN 'destination_arrived' ELSE 'completed' END,j.status,_status,_lat,_lng,nullif(trim(_note),'')); END $$;
CREATE FUNCTION public.arrive_delivery_pickup(_job uuid,_lat double precision DEFAULT NULL,_lng double precision DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF j.rider_id IS DISTINCT FROM auth.uid() OR NOT public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) THEN RAISE EXCEPTION 'Only the assigned active rider may arrive at pickup'; END IF; IF NOT public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Delivery management requires an eligible current plan'; END IF; IF j.status<>'pickup' OR j.pickup_arrived_at IS NOT NULL THEN RAISE EXCEPTION 'Start pickup first; pickup arrival may only be recorded once'; END IF; PERFORM public.validate_delivery_coordinates(_lat,_lng); UPDATE public.delivery_jobs SET pickup_arrived_at=now(),updated_at=now() WHERE id=_job; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,lat,lng) VALUES(_job,j.status,auth.uid(),'pickup_arrived',j.status,j.status,_lat,_lng); END $$;
CREATE OR REPLACE FUNCTION public.ping_delivery_location(_job uuid,_lat double precision,_lng double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _lat IS NULL OR _lng IS NULL THEN RAISE EXCEPTION 'GPS coordinates are required'; END IF; PERFORM public.validate_delivery_coordinates(_lat,_lng); UPDATE public.delivery_jobs j SET rider_lat=_lat,rider_lng=_lng,rider_seen_at=now(),updated_at=now() WHERE id=_job AND rider_id=auth.uid() AND assignment_state='assigned' AND public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) AND public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') AND public.delivery_workflow_status(j.status) IN ('in_process','pickup','in_transit','arrived','returning'); IF NOT FOUND THEN RAISE EXCEPTION 'GPS rejected: delivery is not active or you are not its assigned active rider'; END IF; END $$;
CREATE FUNCTION public.delivery_exception(_job uuid,_action text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; target text; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF coalesce(trim(_reason),'')='' OR length(_reason)>500 THEN RAISE EXCEPTION 'Give an exception reason (max 500 characters)'; END IF; IF j.status IN ('delivered','cancelled','returned') THEN RAISE EXCEPTION 'Delivery already closed'; END IF; IF _action IN ('cancel','reassign') THEN IF NOT public.can_write_pharmacy(j.pharmacy_id,ARRAY['manager']::public.user_role[]) THEN RAISE EXCEPTION 'Only an authorized owner, manager or administrator may cancel or reassign'; END IF; IF _action='reassign' AND public.delivery_workflow_status(j.status) NOT IN ('in_process','pickup') THEN RAISE EXCEPTION 'Reassignment is only allowed before collection'; END IF; target:=CASE _action WHEN 'cancel' THEN 'cancelled' ELSE j.status END; ELSE IF j.rider_id IS DISTINCT FROM auth.uid() OR NOT public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) OR NOT public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery') THEN RAISE EXCEPTION 'Only the assigned active rider may report delivery failure or return'; END IF; target:=CASE WHEN _action='failed' AND public.delivery_workflow_status(j.status) IN ('in_process','pickup','in_transit','arrived') THEN 'failed' WHEN _action='start_return' AND j.status='failed' THEN 'returning' WHEN _action='returned' AND j.status='returning' THEN 'returned' END; IF target IS NULL THEN RAISE EXCEPTION 'Invalid failure/return sequence'; END IF; END IF; UPDATE public.delivery_jobs SET status=target,exception_reason=trim(_reason),updated_at=now(),cancelled_at=CASE WHEN target='cancelled' THEN now() ELSE cancelled_at END,failed_at=CASE WHEN target='failed' THEN now() ELSE failed_at END,returned_at=CASE WHEN target='returned' THEN now() ELSE returned_at END,rider_id=CASE WHEN _action='reassign' THEN NULL ELSE rider_id END,assignment_state=CASE WHEN _action='reassign' THEN 'available' ELSE assignment_state END,accepted_at=CASE WHEN _action='reassign' THEN NULL ELSE accepted_at END,pickup_started_at=CASE WHEN _action='reassign' THEN NULL ELSE pickup_started_at END,pickup_arrived_at=CASE WHEN _action='reassign' THEN NULL ELSE pickup_arrived_at END WHERE id=_job; IF _action='reassign' THEN UPDATE public.delivery_jobs SET status='in_process' WHERE id=_job; target:='in_process'; END IF; INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,note) VALUES(_job,target,auth.uid(),_action,j.status,target,trim(_reason)); END $$;
CREATE OR REPLACE FUNCTION public.add_delivery_note(_job uuid,_note text,_lat double precision,_lng double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; BEGIN SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF NOT (public.can_write_pharmacy(j.pharmacy_id,ARRAY['manager','pharmacist','cashier','inventory_manager']::public.user_role[]) OR (j.rider_id=auth.uid() AND public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) AND public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery'))) THEN RAISE EXCEPTION 'You cannot add delivery notes'; END IF; IF coalesce(trim(_note),'')='' OR length(_note)>500 THEN RAISE EXCEPTION 'Write a short update (max 500 characters)'; END IF; PERFORM public.validate_delivery_coordinates(_lat,_lng); INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,lat,lng,note) VALUES(_job,'update',auth.uid(),'note',j.status,j.status,_lat,_lng,trim(_note)); END $$;

CREATE FUNCTION public.notify_delivery_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; uid uuid; BEGIN IF NEW.action='note' THEN RETURN NEW; END IF; SELECT * INTO j FROM public.delivery_jobs WHERE id=NEW.job_id; FOR uid IN SELECT p.owner_id FROM public.pharmacies p WHERE p.id IN (j.pharmacy_id,j.buyer_pharmacy_id) AND p.owner_id IS NOT NULL UNION SELECT m.user_id FROM public.pharmacy_memberships m WHERE m.pharmacy_id IN (j.pharmacy_id,j.buyer_pharmacy_id) AND m.is_active=true AND m.employment_status='active' AND m.role IN ('manager','cashier','pharmacist','inventory_manager') UNION SELECT j.rider_id WHERE j.rider_id IS NOT NULL UNION SELECT m.user_id FROM public.pharmacy_memberships m WHERE NEW.action IN ('created','reassign') AND m.pharmacy_id=j.pharmacy_id AND public.is_active_delivery_rider(j.pharmacy_id,m.user_id) LOOP PERFORM public.notify_user(uid,j.pharmacy_id,CASE WHEN NEW.action IN ('failed','cancel') THEN 'warning' ELSE 'info' END,'Delivery '||j.tracking_number,replace(NEW.action,'_',' ')||' · '||NEW.new_status,'/pharmacy?id='||j.pharmacy_id); END LOOP; IF NEW.action='reassign' AND NEW.actor_id IS NOT NULL THEN NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_delivery_event AFTER INSERT ON public.delivery_job_events FOR EACH ROW EXECUTE FUNCTION public.notify_delivery_event();
CREATE OR REPLACE FUNCTION public.get_public_delivery_tracking(_job uuid) RETURNS json LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT json_build_object('id',j.id,'tracking_number',j.tracking_number,'status',j.status,'workflow_status',public.delivery_workflow_status(j.status),'pickup_address',j.pickup_address,'dropoff_address',j.dropoff_address,'pickup_lat',j.pickup_lat,'pickup_lng',j.pickup_lng,'dropoff_lat',j.dropoff_lat,'dropoff_lng',j.dropoff_lng,'rider_lat',CASE WHEN j.status IN ('delivered','cancelled','returned','failed') THEN NULL ELSE j.rider_lat END,'rider_lng',CASE WHEN j.status IN ('delivered','cancelled','returned','failed') THEN NULL ELSE j.rider_lng END,'rider_seen_at',j.rider_seen_at,'created_at',j.created_at,'pickup_started_at',j.pickup_started_at,'pickup_arrived_at',j.pickup_arrived_at,'collected_at',j.collected_at,'destination_arrived_at',j.destination_arrived_at,'delivered_at',j.delivered_at,'cancelled_at',j.cancelled_at,'failed_at',j.failed_at,'returned_at',j.returned_at) FROM public.delivery_jobs j WHERE j.id=_job LIMIT 1 $$;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('delivery_workflow_status','validate_delivery_coordinates','is_active_delivery_rider','delivery_event_context','delivery_event_append_only','validate_delivery_job_workflow','create_sale_delivery','accept_delivery_offer','advance_delivery_job','arrive_delivery_pickup','ping_delivery_location','delivery_exception','add_delivery_note','notify_delivery_event') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.signature); IF r.signature::text NOT LIKE '%context(%' AND r.signature::text NOT LIKE '%append_only(%' AND r.signature::text NOT LIKE '%job_workflow(%' AND r.signature::text NOT LIKE '%notify_delivery_event(%' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.signature); END IF; END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.delivery_workflow_status(text) TO anon;
REVOKE ALL ON FUNCTION public.get_public_delivery_tracking(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_delivery_tracking(uuid) TO anon,authenticated,service_role;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='delivery_jobs') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.delivery_jobs; END IF; IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='delivery_job_events') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.delivery_job_events; END IF; END $$;